"use client";

import { useState, useEffect } from "react";
import { supabase } from "@/lib/supabaseClient";
import { useRouter } from "next/navigation";
import { Dumbbell, Eye, EyeOff, CheckCircle2, XCircle } from "lucide-react";

export default function Signup() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [formError, setFormError] = useState("");

  // Field states
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [username, setUsername] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const [showPassword, setShowPassword] = useState(false);

  // Validation States
  const [usernameStatus, setUsernameStatus] = useState<"idle" | "checking" | "available" | "taken">("idle");
  
  // Validation Helpers
  const isValidName = (name: string) => /^[a-zA-Z]{2,}$/.test(name);
  const isValidUsernameFormat = (user: string) => /^[^\s]{4,}$/.test(user);
  const isValidEmail = (email: string) => /^\S+@\S+\.\S+$/.test(email);
  const isValidPassword = (pass: string) => 
    pass.length >= 8 &&
    /[A-Z]/.test(pass) &&
    /[a-z]/.test(pass) &&
    /[0-9]/.test(pass) &&
    /[^A-Za-z0-9]/.test(pass);

  // Debounced Username Uniqueness Check
  useEffect(() => {
    if (!isValidUsernameFormat(username)) {
      setUsernameStatus("idle");
      return;
    }
    
    setUsernameStatus("checking");
    const timeoutId = setTimeout(async () => {
      const { data, error } = await supabase
        .from("users")
        .select("id")
        .eq("username", username)
        .single();
      
      if (data) {
        setUsernameStatus("taken");
      } else {
        setUsernameStatus("available");
      }
    }, 500);

    return () => clearTimeout(timeoutId);
  }, [username]);

  // Overall form validity
  const isFormValid = 
    isValidName(firstName) &&
    isValidName(lastName) &&
    isValidUsernameFormat(username) &&
    usernameStatus === "available" &&
    isValidEmail(email) &&
    isValidPassword(password);

  const handleSignup = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!isFormValid) return;
    
    setLoading(true);
    setFormError("");

    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: {
          first_name: firstName,
          last_name: lastName,
          username: username
        }
      }
    });

    if (error) {
      setFormError(error.message);
      setLoading(false);
    } else {
      // Directs directly to onboarding!
      router.push("/onboarding");
    }
  };

  return (
    <div className="min-h-screen bg-background flex flex-col items-center justify-center p-6 py-12">
      <div className="mb-8 text-center animate-in fade-in slide-in-from-bottom-5 duration-700">
        <h1 className="text-3xl font-black uppercase tracking-widest text-primary flex items-center justify-center gap-2">
          <Dumbbell className="w-6 h-6" /> Join The Call
        </h1>
        <p className="text-gray-500 font-semibold tracking-wide uppercase text-xs mt-2">
          Commit to 75 Days of Discipline
        </p>
      </div>

      <div className="w-full max-w-md bg-dark-panel p-8 rounded-3xl border border-border shadow-2xl animate-in fade-in zoom-in-95 duration-500 delay-150">
        {formError && (
          <div className="mb-6 p-4 bg-red-500/10 border border-red-500/30 rounded-xl text-red-500 text-sm font-semibold text-center">
            {formError}
          </div>
        )}

        <form onSubmit={handleSignup} className="flex flex-col gap-5">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs uppercase tracking-widest font-bold text-gray-400 mb-2">First Name</label>
              <input
                type="text"
                value={firstName}
                onChange={(e) => setFirstName(e.target.value)}
                className={`w-full bg-background border rounded-xl p-3 text-white focus:outline-none transition ${firstName.length > 0 ? (isValidName(firstName) ? 'border-success/50 focus:border-success' : 'border-red-500/50 focus:border-red-500') : 'border-border focus:border-primary'}`}
                placeholder="John"
              />
              {firstName.length > 0 && !isValidName(firstName) && (
                <p className="text-[10px] text-red-500 mt-1 font-semibold uppercase tracking-wide">Min 2 chars, letters only</p>
              )}
            </div>
            <div>
              <label className="block text-xs uppercase tracking-widest font-bold text-gray-400 mb-2">Last Name</label>
              <input
                type="text"
                value={lastName}
                onChange={(e) => setLastName(e.target.value)}
                className={`w-full bg-background border rounded-xl p-3 text-white focus:outline-none transition ${lastName.length > 0 ? (isValidName(lastName) ? 'border-success/50 focus:border-success' : 'border-red-500/50 focus:border-red-500') : 'border-border focus:border-primary'}`}
                placeholder="Doe"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs uppercase tracking-widest font-bold text-gray-400 mb-2">Username</label>
            <div className="relative">
              <input
                type="text"
                value={username}
                onChange={(e) => setUsername(e.target.value.toLowerCase())}
                className={`w-full bg-background border rounded-xl p-3 text-white focus:outline-none transition pr-10 ${username.length > 0 ? (isValidUsernameFormat(username) && usernameStatus === 'available' ? 'border-success/50 focus:border-success' : 'border-red-500/50 focus:border-red-500') : 'border-border focus:border-primary'}`}
                placeholder="johndoe75"
              />
              <div className="absolute inset-y-0 right-3 flex items-center">
                {usernameStatus === 'checking' && <Dumbbell className="w-4 h-4 animate-spin text-gray-500" />}
                {usernameStatus === 'available' && <CheckCircle2 className="w-4 h-4 text-success" />}
                {usernameStatus === 'taken' && <XCircle className="w-4 h-4 text-red-500" />}
              </div>
            </div>
            {username.length > 0 && !isValidUsernameFormat(username) && <p className="text-[10px] text-red-500 mt-1 font-semibold uppercase tracking-wide">Min 4 chars, no spaces</p>}
            {usernameStatus === 'taken' && <p className="text-[10px] text-red-500 mt-1 font-semibold uppercase tracking-wide">Username taken. Try another.</p>}
          </div>

          <div>
            <label className="block text-xs uppercase tracking-widest font-bold text-gray-400 mb-2">Email Address</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className={`w-full bg-background border rounded-xl p-3 text-white focus:outline-none transition ${email.length > 0 ? (isValidEmail(email) ? 'border-success/50 focus:border-success' : 'border-red-500/50 focus:border-red-500') : 'border-border focus:border-primary'}`}
              placeholder="you@example.com"
            />
          </div>

          <div>
            <label className="block text-xs uppercase tracking-widest font-bold text-gray-400 mb-2">Password</label>
            <div className="relative">
              <input
                type={showPassword ? "text" : "password"}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className={`w-full bg-background border rounded-xl p-3 pr-12 text-white focus:outline-none transition ${password.length > 0 ? (isValidPassword(password) ? 'border-success/50 focus:border-success' : 'border-red-500/50 focus:border-red-500') : 'border-border focus:border-primary'}`}
                placeholder="••••••••"
              />
              <button 
                type="button" 
                onClick={() => setShowPassword(!showPassword)}
                className="absolute inset-y-0 right-3 flex items-center text-gray-500 hover:text-white transition"
              >
                {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
              </button>
            </div>
            {password.length > 0 && !isValidPassword(password) && (
              <p className="text-[10px] text-red-500 mt-2 font-semibold uppercase tracking-wide leading-tight">Must contain 8+ characters, including 1 uppercase, 1 lowercase, 1 number, and 1 special character.</p>
            )}
          </div>

          <button
            type="submit"
            disabled={!isFormValid || loading}
            className={`mt-4 py-4 rounded-xl font-black uppercase tracking-widest transition-all duration-300 text-sm flex items-center justify-center ${
              isFormValid && !loading
                ? "bg-primary text-white hover:bg-primary-hover shadow-lg hover:-translate-y-0.5"
                : "bg-background border border-border text-gray-600 cursor-not-allowed"
            }`}
          >
            {loading ? <Dumbbell className="w-5 h-5 animate-spin" /> : "Commit to 75 Hard"}
          </button>
          
          <button
            type="button"
            onClick={() => router.push("/login")}
            className="text-xs text-center text-gray-500 font-bold uppercase tracking-widest hover:text-white transition mt-2"
          >
            Already in the program? <span className="text-primary hover:underline ml-1">Log In</span>
          </button>
        </form>
      </div>
    </div>
  );
}
